INSERT INTO identity.roles(id,name,identity_type,sub_role,description,data_scope,permissions,sensitive_fields) VALUES
('role_hq_admin','总部运营管理员','admin',NULL,'可管理全部18个授权业务模块与跨门店范围；成本价与期末处理需单独开启。','all_stores',ARRAY['workbench.read','basic.read','basic.product.read','basic.product.create','basic.product.update','basic.product.delete','basic.product.import','basic.product.export','basic.product.cost.read','basic.customer.read','basic.staff.read','basic.supplier.read','basic.brand.read','basic.fee.read','sales.read','sales.pos.create','sales.order.read','sales.discount.override','sales.settings.manage','purchase.read','purchase.create','purchase.approve','transfer.read','transfer.create','inventory.read','inventory.adjust.doc','after_sales.read','reports.read','finance.read','finance.audit','contact_lenses.read','members.read','members.profile.read','members.profile.create','members.followup.notification.read','members.followup.notification.send','members.points.read','members.recharge.read','members.appointments.read','members.marketing.read','members.settings.manage','members.analytics.read','members.optometry.read','processing.read','vision_records.read','vision_screening.read','orthokeratology.read','brands.read','brands.order.create','marketing.read','system.read','system.role.manage','system.user.manage','system.store.manage','help.read']::text[],'{"viewCostPrice": true, "viewWholesalePrice": true, "viewProfitMargin": true, "viewPlaintextPhone": false, "batchExport": true}'::jsonb),
('role_store_manager','门店店长','store','store_manager','仅访问所辖门店的销售、库存、会员、视光、加工与门店报表，无系统全局设置权。','assigned_stores',ARRAY['workbench.read','basic.read','basic.product.read','basic.product.export','basic.customer.read','basic.brand.read','basic.fee.read','sales.read','sales.pos.create','sales.order.read','sales.discount.override','purchase.read','purchase.create','transfer.read','transfer.create','inventory.read','inventory.adjust.doc','after_sales.read','reports.read','contact_lenses.read','members.read','members.profile.read','members.profile.create','members.followup.notification.read','members.followup.notification.send','members.points.read','members.recharge.read','members.appointments.read','members.analytics.read','members.optometry.read','processing.read','vision_records.read','vision_screening.read','orthokeratology.read','brands.read','marketing.read','help.read']::text[],'{"viewCostPrice": false, "viewWholesalePrice": true, "viewProfitMargin": false, "viewPlaintextPhone": false, "batchExport": true}'::jsonb),
('role_store_guide','门店导购员','store','store_guide','聚焦门店开单、商品查询、会员接待与复查提醒，受限查看采购成本与财务台账。','assigned_stores',ARRAY['workbench.read','basic.read','basic.product.read','basic.customer.read','sales.read','sales.pos.create','sales.order.read','inventory.read','after_sales.read','members.read','members.profile.read','members.followup.notification.read','members.appointments.read','processing.read','help.read']::text[],'{"viewCostPrice": false, "viewWholesalePrice": false, "viewProfitMargin": false, "viewPlaintextPhone": false, "batchExport": false}'::jsonb),
('role_store_optometrist','门店高级验光师','store','store_optometrist','负责视光档案、角膜塑形检查、视力筛查与复查通知，不接触成本及财务审批。','assigned_stores',ARRAY['workbench.read','basic.read','basic.product.read','sales.read','sales.order.read','contact_lenses.read','members.read','members.profile.read','members.followup.notification.read','members.followup.notification.send','members.appointments.read','members.optometry.read','processing.read','vision_records.read','vision_screening.read','orthokeratology.read','help.read']::text[],'{"viewCostPrice": false, "viewWholesalePrice": false, "viewProfitMargin": false, "viewPlaintextPhone": false, "batchExport": false}'::jsonb),
('role_supplier_partner','合作供应商账号','supplier',NULL,'供应商专属工作台与品牌专区：仅查看自身供货商品、采购交付、退货及往来对账，严格隔离顾客、会员、视光与内部利润。','own_supplier',ARRAY['workbench.read','basic.read','basic.product.read','purchase.read','after_sales.read','finance.read','brands.read','brands.order.create','help.read']::text[],'{"viewCostPrice": false, "viewWholesalePrice": true, "viewProfitMargin": false, "viewPlaintextPhone": false, "batchExport": false}'::jsonb)
INSERT INTO identity.user_access(user_id,role_id,store_ids) SELECT u.id, CASE u.username WHEN 'admin' THEN 'role_hq_admin' WHEN 'manager' THEN 'role_store_manager' WHEN 'guide' THEN 'role_store_guide' WHEN 'optometrist' THEN 'role_store_optometrist' WHEN 'supplier' THEN 'role_supplier_partner' END, COALESCE(s.store_ids,'{}'::text[]) FROM identity.users u LEFT JOIN identity.user_purchase_scopes s ON s.user_id=u.id WHERE u.username IN ('admin','manager','guide','optometrist','supplier') ON CONFLICT(user_id) DO NOTHING;
